package com.algoverse;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.util.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.data.mongodb.core.query.*;
import org.springframework.data.domain.Sort;
import org.springframework.web.util.HtmlUtils;
import static org.springframework.data.mongodb.core.query.Criteria.where;
import static com.algoverse.Errors.*;
@RestController @RequestMapping("/api/admin")
public class AdminController {
 final Store store;final PasswordEncoder passwords;
 AdminController(Store store,PasswordEncoder passwords){this.store=store;this.passwords=passwords;}
 @GetMapping("/analytics") Object analytics(){return Map.of("users",store.mongo.count(new Query(),Data.User.class),"activeUsers",store.mongo.count(Query.query(where("active").is(true)),Data.User.class),"submissions",store.mongo.count(new Query(),Data.Submission.class),"accepted",store.mongo.count(Query.query(where("accepted").is(true)),Data.Submission.class),"completedLessons",store.mongo.count(Query.query(where("completed").is(true)),Data.Learning.class),"audit",store.mongo.find(new Query().with(Sort.by(Sort.Direction.DESC,"createdAt")).limit(50),Data.Audit.class));}
 @GetMapping("/users") Object users(@RequestParam(defaultValue="")String search,@RequestParam(defaultValue="0")int page){check(search.length()<=100&&page>=0&&page<=10000,"Invalid search.");var q=new Query();if(!search.isBlank()){var regex=java.util.regex.Pattern.compile(java.util.regex.Pattern.quote(search),java.util.regex.Pattern.CASE_INSENSITIVE);q.addCriteria(new Criteria().orOperator(where("name").regex(regex),where("email").regex(regex)));}return store.mongo.find(q.with(Sort.by("email")).skip(page*50L).limit(50),Data.User.class).stream().map(Data.User::view).toList();}
 record NewUser(@NotBlank @Size(max=80)String name,@NotBlank @Email @Size(max=254)String email,@NotBlank String password,@NotBlank String role){}
 record UserPatch(@NotBlank @Size(max=80)String name,@NotBlank String role,boolean active,String password){}
 static void role(String role){check(Set.of("student","admin").contains(role),"Invalid role.");}
 Data.User requireUser(String id){var u=store.byId(id,Data.User.class);check(u!=null,"User not found.");return u;}
 @PostMapping("/users") Object create(@Valid @RequestBody NewUser p,HttpServletRequest req){role(p.role());AuthController.validPassword(p.password());var u=new Data.User();u.name=text(p.name(),80);u.email=AuthController.email(p.email());u.role=p.role();u.passwordHash=passwords.encode(p.password());store.mongo.insert(u);store.audit(AuthController.user(req).id,"user.create",u.id);return u.view();}
 @PatchMapping("/users/{id}") synchronized Object update(@PathVariable String id,@Valid @RequestBody UserPatch p,HttpServletRequest req){role(p.role());var u=requireUser(id);if(!p.active()||!p.role().equals("admin"))preserveAdmin(u);check(!id.equals(AuthController.user(req).id)||p.active()&&p.role().equals("admin"),"You cannot disable or demote your own account.");boolean securityChange=!u.role.equals(p.role())||u.active!=p.active()||(p.password()!=null&&!p.password().isBlank());u.name=text(p.name(),80);u.role=p.role();u.active=p.active();if(p.password()!=null&&!p.password().isBlank()){AuthController.validPassword(p.password());u.passwordHash=passwords.encode(p.password());}store.mongo.save(u);if(securityChange)store.revoke(id);store.audit(AuthController.user(req).id,"user.update",id);return u.view();}
 void preserveAdmin(Data.User u){if(u.active&&u.role.equals("admin"))check(store.mongo.count(Query.query(where("role").is("admin").and("active").is(true)),Data.User.class)>1,"Keep at least one active administrator.");}
 @DeleteMapping("/users/{id}") synchronized Object delete(@PathVariable String id,HttpServletRequest req){check(!id.equals(AuthController.user(req).id),"You cannot delete your own account.");var u=requireUser(id);preserveAdmin(u);store.revoke(id);store.mongo.remove(u);for(Class<?> type:List.of(Data.Draft.class,Data.Submission.class,Data.Learning.class,Data.QuizAttempt.class,Data.Hints.class))store.mongo.remove(Query.query(where("userId").is(id)),type);store.mongo.remove(Query.query(where("_id").is(id)),Data.Notes.class);store.audit(AuthController.user(req).id,"user.delete",id);return Map.of("ok",true);}
 @GetMapping("/problems") Object problems(){return store.mongo.findAll(Data.Problem.class);}
 record ProblemBody(@NotBlank @Pattern(regexp="[a-z0-9-]{1,60}")String id,@Min(1)int number,@NotBlank @Size(max=120)String title,@NotBlank String difficulty,@NotBlank @Size(max=15000)String description,@Size(max=3000)String hint,@NotBlank @Size(max=30000)String jsStarter,@NotBlank @Pattern(regexp="[A-Za-z_$][A-Za-z0-9_$]{0,60}")String fnName,@NotNull @Size(max=10)List<String> tags,@NotNull @Size(max=30)List<String> constraints,@NotNull @Size(max=10)List<Map<String,Object>> examples,@NotNull @Size(min=1,max=30)List<Data.TestCase> tests,boolean active,boolean unordered){}
 Data.Problem validated(ProblemBody p){check(Set.of("Easy","Medium","Hard").contains(p.difficulty()),"Invalid difficulty.");check(p.tests().stream().anyMatch(t->!t.hidden),"Add at least one visible sample test.");for(var t:p.tests())check(t.args!=null&&t.args.size()<=10&&t.expected!=null,"Invalid test.");for(String t:p.tags())text(t,100);for(String t:p.constraints())text(t,1000);var v=new Data.Problem();v.id=p.id();v.number=p.number();v.title=p.title();v.difficulty=p.difficulty();v.description=HtmlUtils.htmlEscape(p.description()).replace("\n","<br>");v.hint=p.hint()==null?"":p.hint();v.jsStarter=p.jsStarter();v.fnName=p.fnName();v.tags=p.tags();v.constraints=p.constraints();v.examples=p.examples();v.tests=p.tests();v.active=p.active();v.unordered=p.unordered();return v;}
 @PostMapping("/problems") Object createProblem(@Valid @RequestBody ProblemBody p,HttpServletRequest req){var v=validated(p);store.mongo.insert(v);store.audit(AuthController.user(req).id,"problem.create",v.id);return v;}
 @PutMapping("/problems/{id}") Object problem(@PathVariable String id,@Valid @RequestBody ProblemBody p,HttpServletRequest req){check(id.equals(p.id())&&store.byId(id,Data.Problem.class)!=null,"Problem identifier cannot change.");var v=validated(p);store.mongo.save(v);store.audit(AuthController.user(req).id,"problem.update",id);return v;}
 @DeleteMapping("/problems/{id}") Object deleteProblem(@PathVariable String id,HttpServletRequest req){var p=store.byId(id,Data.Problem.class);check(p!=null,"Problem not found.");p.active=false;store.mongo.save(p);store.audit(AuthController.user(req).id,"problem.archive",id);return Map.of("ok",true);}
 @GetMapping("/lessons") Object lessons(){return store.mongo.findAll(Data.Lesson.class);}
 record LessonPatch(@NotBlank @Size(max=120)String title,@NotBlank @Size(max=4000)String summary,@NotNull @Size(min=1,max=10)List<String> steps,boolean active){}
 @PutMapping("/lessons/{id}") Object lesson(@PathVariable String id,@Valid @RequestBody LessonPatch p,HttpServletRequest req){var l=store.byId(id,Data.Lesson.class);check(l!=null,"Unknown visualizer lesson.");for(String step:p.steps())text(step,1000);l.title=p.title();l.summary=p.summary();l.steps=p.steps();l.active=p.active();store.mongo.save(l);store.audit(AuthController.user(req).id,"lesson.update",id);return l;}
 @GetMapping("/settings") Object settings(){return store.settings();}
 record SettingsBody(@NotBlank @Size(max=80)String platformName,@NotBlank @Size(max=400)String welcomeMessage,boolean registrationEnabled){}
 @PutMapping("/settings") Object settings(@Valid @RequestBody SettingsBody p,HttpServletRequest req){var s=store.settings();s.platformName=p.platformName();s.welcomeMessage=p.welcomeMessage();s.registrationEnabled=p.registrationEnabled();store.mongo.save(s);store.audit(AuthController.user(req).id,"settings.update","platform");return s;}
}
